<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>2048</title>
  <style>
    :root {
      color-scheme: dark;
      --page: #111318;
      --panel: #1b1f27;
      --grid: #303641;
      --empty: #20252e;
      --text: #f7f7f7;
      --muted: #aeb6c3;
      --gap: 12px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      background:
        radial-gradient(circle at top, #242a35 0, var(--page) 55%);
      color: var(--text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
        sans-serif;
    }

    main {
      width: min(92vw, 520px);
    }

    header {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 18px;
      margin-bottom: 18px;
    }

    h1 {
      margin: 0;
      font-size: clamp(3rem, 13vw, 5rem);
      line-height: 0.9;
      letter-spacing: -0.07em;
    }

    .controls {
      display: flex;
      align-items: stretch;
      gap: 10px;
    }

    .score-box {
      min-width: 92px;
      padding: 8px 14px;
      border-radius: 8px;
      background: var(--panel);
      text-align: center;
      box-shadow: 0 8px 24px #0005;
    }

    .score-label {
      display: block;
      color: var(--muted);
      font-size: 0.72rem;
      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    #score {
      display: block;
      margin-top: 2px;
      font-size: 1.45rem;
      font-weight: 800;
    }

    #reset {
      border: 0;
      border-radius: 8px;
      padding: 0 16px;
      background: #e76f51;
      color: white;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 8px 24px #0005;
    }

    #reset:hover {
      background: #f07c5d;
    }

    #reset:focus-visible {
      outline: 3px solid #fff;
      outline-offset: 3px;
    }

    #board {
      width: 100%;
      aspect-ratio: 1;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      grid-template-rows: repeat(4, 1fr);
      gap: var(--gap);
      padding: var(--gap);
      border-radius: 14px;
      background: var(--grid);
      box-shadow: 0 20px 60px #0008;
    }

    .tile {
      min-width: 0;
      display: grid;
      place-items: center;
      border-radius: 9px;
      background: var(--empty);
      color: white;
      font-size: clamp(1.25rem, 7vw, 2.7rem);
      font-weight: 900;
      line-height: 1;
      user-select: none;
    }

    .tile[data-value="2"]    { background: #546a7b; }
    .tile[data-value="4"]    { background: #607d8b; }
    .tile[data-value="8"]    { background: #d17b49; }
    .tile[data-value="16"]   { background: #d96545; }
    .tile[data-value="32"]   { background: #c94f4f; }
    .tile[data-value="64"]   { background: #b83b5e; }
    .tile[data-value="128"]  { background: #9c6ade; font-size: clamp(1.1rem, 6vw, 2.25rem); }
    .tile[data-value="256"]  { background: #7655c6; font-size: clamp(1.1rem, 6vw, 2.25rem); }
    .tile[data-value="512"]  { background: #4e73c2; font-size: clamp(1.1rem, 6vw, 2.25rem); }
    .tile[data-value="1024"] { background: #278ea5; font-size: clamp(0.95rem, 5vw, 1.9rem); }
    .tile[data-value="2048"] { background: #21a179; font-size: clamp(0.95rem, 5vw, 1.9rem); }
    .tile.high              { background: #13a89e; font-size: clamp(0.8rem, 4.5vw, 1.6rem); }

    .hint {
      margin: 16px 0 0;
      color: var(--muted);
      text-align: center;
      font-size: 0.95rem;
    }

    @media (max-width: 430px) {
      :root {
        --gap: 8px;
      }

      header {
        align-items: center;
      }

      .controls {
        gap: 6px;
      }

      .score-box {
        min-width: 74px;
        padding-inline: 9px;
      }

      #reset {
        padding-inline: 10px;
      }
    }
  </style>
</head>
<body>
  <main>
    <header>
      <h1>2048</h1>
      <div class="controls">
        <div class="score-box">
          <span class="score-label">Score</span>
          <span id="score">0</span>
        </div>
        <button id="reset" type="button">New Game</button>
      </div>
    </header>

    <div id="board" aria-label="2048 game board"></div>
    <p class="hint">Use the arrow keys to move the tiles.</p>
  </main>

  <script>
    (() => {
      "use strict";

      const SIZE = 4;
      const boardElement = document.getElementById("board");
      const scoreElement = document.getElementById("score");
      const resetButton = document.getElementById("reset");

      let grid = createEmptyGrid();
      let currentScore = 0;

      function createEmptyGrid() {
        return Array.from({ length: SIZE }, () => Array(SIZE).fill(0));
      }

      function cloneGrid(source) {
        return source.map(row => row.slice());
      }

      function render() {
        boardElement.replaceChildren();

        for (let row = 0; row < SIZE; row++) {
          for (let column = 0; column < SIZE; column++) {
            const value = grid[row][column];
            const tile = document.createElement("div");
            tile.className = "tile";
            tile.dataset.value = String(value);

            if (value > 2048) {
              tile.classList.add("high");
            }

            tile.textContent = value === 0 ? "" : String(value);
            tile.setAttribute(
              "aria-label",
              value === 0 ? "Empty cell" : `Tile ${value}`
            );
            boardElement.appendChild(tile);
          }
        }

        scoreElement.textContent = String(currentScore);
      }

      function addRandomTile() {
        const emptyCells = [];

        for (let row = 0; row < SIZE; row++) {
          for (let column = 0; column < SIZE; column++) {
            if (grid[row][column] === 0) {
              emptyCells.push([row, column]);
            }
          }
        }

        if (emptyCells.length === 0) return false;

        const [row, column] =
          emptyCells[Math.floor(Math.random() * emptyCells.length)];

        grid[row][column] = Math.random() < 0.9 ? 2 : 4;
        return true;
      }

      function gridsEqual(a, b) {
        for (let row = 0; row < SIZE; row++) {
          for (let column = 0; column < SIZE; column++) {
            if (a[row][column] !== b[row][column]) return false;
          }
        }
        return true;
      }

      function mergeLine(values) {
        const compacted = values.filter(value => value !== 0);
        const merged = [];

        for (let index = 0; index < compacted.length; index++) {
          if (
            index + 1 < compacted.length &&
            compacted[index] === compacted[index + 1]
          ) {
            const newValue = compacted[index] * 2;
            merged.push(newValue);
            currentScore += newValue;
            index++;
          } else {
            merged.push(compacted[index]);
          }
        }

        while (merged.length < SIZE) {
          merged.push(0);
        }

        return merged;
      }

      function coordinatesFor(direction, line) {
        const coordinates = [];

        for (let position = 0; position < SIZE; position++) {
          if (direction === "left") {
            coordinates.push([line, position]);
          } else if (direction === "right") {
            coordinates.push([line, SIZE - 1 - position]);
          } else if (direction === "up") {
            coordinates.push([position, line]);
          } else {
            coordinates.push([SIZE - 1 - position, line]);
          }
        }

        return coordinates;
      }

      function move(direction) {
        if (!["left", "right", "up", "down"].includes(direction)) {
          return false;
        }

        const before = cloneGrid(grid);

        for (let line = 0; line < SIZE; line++) {
          const coordinates = coordinatesFor(direction, line);
          const values = coordinates.map(([row, column]) => grid[row][column]);
          const result = mergeLine(values);

          coordinates.forEach(([row, column], index) => {
            grid[row][column] = result[index];
          });
        }

        const changed = !gridsEqual(before, grid);

        if (changed) {
          addRandomTile();
        }

        render();
        return changed;
      }

      function reset() {
        grid = createEmptyGrid();
        currentScore = 0;
        addRandomTile();
        addRandomTile();
        render();
      }

      function setBoard(arr) {
        if (
          !Array.isArray(arr) ||
          arr.length !== SIZE ||
          arr.some(row => !Array.isArray(row) || row.length !== SIZE)
        ) {
          throw new TypeError("Board must be a 4x4 array.");
        }

        grid = arr.map(row =>
          row.map(value => {
            if (!Number.isFinite(value) || value < 0) {
              throw new TypeError("Board values must be non-negative numbers.");
            }
            return value;
          })
        );

        render();
      }

      window.game = {
        size: SIZE,
        reset,
        move,
        board() {
          return cloneGrid(grid);
        },
        setBoard,
        score() {
          return currentScore;
        }
      };

      const keyDirections = {
        ArrowLeft: "left",
        ArrowRight: "right",
        ArrowUp: "up",
        ArrowDown: "down"
      };

      window.addEventListener("keydown", event => {
        const direction = keyDirections[event.key];
        if (!direction) return;

        event.preventDefault();
        move(direction);
      });

      resetButton.addEventListener("click", reset);
      reset();
    })();
  </script>
</body>
</html>
